def _prototype(code: str) -> str | None:
    """Return Binja's function declarator without its body."""
    brace = code.find("{")
    if brace < 0:
        return None
    head = code[:brace].strip()
    head = _LOCATION.sub("", head)
    head = re.sub(r"\s+__(?:noreturn|pure)\b", "", head)
    head = re.sub(
        r"^([^\n()]+?)\s*\(\s*(\*+(?:\s+const)?)\s*\)\s*"
        r"(\[[^\]\n]+\])\s+([A-Za-z_$][\w$]*)\(([^()\n]*)\)",
        r"\1 (\2 \4(\5))\3",
        head,
        count=1,
    )
    head = re.sub(
        r"^([^\n()]+?)\s*\(\s*(\*+(?:\s+const)?)\s*\)\(([^()\n]*)\)\s+"
        r"([A-Za-z_$][\w$]*)\(([^()\n]*)\)",
        r"\1 (\2 \4(\5))(\3)",
        head,
        count=1,
    )
    if not head or ";" in head or "(" not in head:
        return None
    return head + ";"


